Object.assign(SNIP,{});PRESET_NOTES["l66"]={"Ví dụ: Thuật toán Euclid": "252, 105 → 105, 42 → 42, 21 → 21, 0: gcd = 21. Hai số 17 và 5 nguyên tố cùng nhau: gcd = 1. gcd(0, 9) = 9.", "Ví dụ: Bội chung nhỏ nhất": "lcm(4, 6) = 12, lcm(12, 18) = 36; lcm của 2..6 = 60. Hai số xấp xỉ 10^9 nguyên tố cùng nhau có lcm cỡ 10^18 — vẫn vừa long long.", "Ví dụ: Cộng, trừ, nhân theo modulo": "x = 5 − 13 = −8: trong C++ x % 7 = −1 (dấu theo số bị chia), còn đáp án toán học là 6. Công thức (x % m + m) % m luôn cho kết quả trong [0, m). 20! mod (10^9 + 7) = 146326063.", "Ví dụ: Lũy thừa nhanh": "3^13 = 1594323, ba chữ số cuối 323. 2^(10^18) mod (10^9 + 7) chỉ cần khoảng 60 vòng lặp.", "Lỗi: tràn số khi nhân trước khi lấy dư": "10^6 · 10^6 = 10^12 vượt xa giới hạn int (khoảng 2,1 · 10^9): kết quả bị quấn vòng thành số rác, ở đây là −727379968. Đáp án đúng 999993007. Viết 1LL * a * b hoặc khai báo long long ngay từ đầu."};EX_HINTS["l66"]=[["Cạnh gạch phải chia hết cả W và H; lớn nhất là gcd(W, H).", "Số viên = (W / g) · (H / g). Có thể tới 10^18: dùng long long.", "Thử từng cạnh từ min(W, H) trở xuống tốn tới 10^9 bước mỗi phòng; Euclid chỉ vài chục bước."], ["kq = 1; a = a mod m; khi b > 0: nếu b lẻ thì kq = kq · a mod m; a = a · a mod m; b = b / 2.", "Lấy a mod m trước: a có thể tới 10^9 > m. Khi m = 1, đáp án luôn 0: khởi tạo kq = 1 % m.", "Nhân b lần tốn tới 10^18 bước — không bao giờ xong."], ["Đáp án là bội chung nhỏ nhất của cả dãy: gộp dần kq = lcm(kq, t_i).", "lcm(a, b) = a / gcd(a, b) · b. Viết a · b / gcd thì a · b có thể vượt 10^18 dù đáp án vừa.", "Bội chung của các số đã gộp không bao giờ giảm, nên mọi giá trị trung gian ≤ đáp án ≤ 10^18."]];
/* ===================== BÀI 66 · Ước chung lớn nhất, bội chung nhỏ nhất, đồng dư và lũy thừa nhanh ===================== */
/* Bài 66 · Ước chung lớn nhất, bội chung nhỏ nhất, đồng dư và lũy thừa nhanh
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR66=[{label:"Ví dụ: Thuật toán Euclid",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nlong long ucln(long long a, long long b) {\n    while (b != 0) {\n        long long r = a % b;           // gcd(a, b) = gcd(b, a mod b)\n        a = b;\n        b = r;\n    }\n    return a;\n}\n\nint main() {\n    cout << ucln(252, 105) << \" \" << ucln(17, 5) << \" \" << ucln(0, 9) << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","r"]}],py:{code:"def ucln(a, b):\n    while b != 0:\n        a, b = b, a % b                # gcd(a, b) = gcd(b, a mod b)\n    return a\n\nprint(ucln(252, 105), ucln(17, 5), ucln(0, 9))"},cs:{code:"using System;\n\nclass Program\n{\n    static long Ucln(long a, long b)\n    {\n        while (b != 0)\n        {\n            long r = a % b;                // gcd(a, b) = gcd(b, a mod b)\n            a = b;\n            b = r;\n        }\n        return a;\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Ucln(252, 105) + \" \" + Ucln(17, 5) + \" \" + Ucln(0, 9));\n    }\n}"}},{label:"Ví dụ: Bội chung nhỏ nhất",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nlong long ucln(long long a, long long b) { return b == 0 ? a : ucln(b, a % b); }\n\nlong long bcnn(long long a, long long b) {\n    return a / ucln(a, b) * b;         // chia trước, nhân sau: không tràn trung gian\n}\n\nint main() {\n    cout << bcnn(4, 6) << \" \" << bcnn(12, 18) << \"\\n\";\n    long long ds[] = {2, 3, 4, 5, 6};\n    long long l = 1;\n    for (long long x : ds) l = bcnn(l, x);   // lcm của cả dãy\n    cout << l << \"\\n\";\n    cout << bcnn(1000000000, 999999999) << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","l"]}],py:{code:"def ucln(a, b):\n    return a if b == 0 else ucln(b, a % b)\n\ndef bcnn(a, b):\n    return a // ucln(a, b) * b         # chia trước, nhân sau: số trung gian nhỏ\n\nprint(bcnn(4, 6), bcnn(12, 18))\nl = 1\nfor x in [2, 3, 4, 5, 6]:\n    l = bcnn(l, x)                     # lcm của cả dãy\nprint(l)\nprint(bcnn(1000000000, 999999999))"},cs:{code:"using System;\n\nclass Program\n{\n    static long Ucln(long a, long b) { return b == 0 ? a : Ucln(b, a % b); }\n\n    static long Bcnn(long a, long b)\n    {\n        return a / Ucln(a, b) * b;         // chia trước, nhân sau: không tràn trung gian\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Bcnn(4, 6) + \" \" + Bcnn(12, 18));\n        long[] ds = { 2, 3, 4, 5, 6 };\n        long l = 1;\n        foreach (long x in ds) l = Bcnn(l, x); // lcm của cả dãy\n        Console.WriteLine(l);\n        Console.WriteLine(Bcnn(1000000000, 999999999));\n    }\n}"}},{label:"Ví dụ: Cộng, trừ, nhân theo modulo",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    const long long M = 1000000007;\n    long long a = 999999999, b = 123456789;\n    cout << (a + b) % M << \"\\n\";\n    cout << (a * b) % M << \"\\n\";       // a · b < 10^18: vừa long long\n    long long x = 5 - 13;\n    cout << x % 7 << \" \" << (x % 7 + 7) % 7 << \"\\n\";   // số âm: cộng thêm m\n    long long gt = 1;\n    for (int i = 1; i <= 20; i++) gt = gt * i % M;     // 20! mod M, lấy dư sau mỗi bước\n    cout << gt << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","x","i","gt"]}],py:{code:"M = 1000000007\na, b = 999999999, 123456789\nprint((a + b) % M)\nprint(a * b % M)\nx = 5 - 13\nprint(x % 7)                           # Python: kết quả luôn cùng dấu với số chia, ra 6\ngt = 1\nfor i in range(1, 21):\n    gt = gt * i % M                    # 20! mod M, lấy dư sau mỗi bước\nprint(gt)",note:"Python không tràn số và % luôn cho kết quả trong [0, m) khi m > 0: −8 % 7 = 6. Dù vậy vẫn nên lấy dư sau mỗi bước: số nguyên khổng lồ làm phép tính chậm dần."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const long M = 1000000007;\n        long a = 999999999, b = 123456789;\n        Console.WriteLine((a + b) % M);\n        Console.WriteLine(a * b % M);          // a · b < 10^18: vừa long\n        long x = 5 - 13;\n        Console.WriteLine(x % 7 + \" \" + (x % 7 + 7) % 7);   // số âm: cộng thêm m\n        long gt = 1;\n        for (int i = 1; i <= 20; i++) gt = gt * i % M;      // 20! mod M, lấy dư sau mỗi bước\n        Console.WriteLine(gt);\n    }\n}",note:"x = 5 − 13 = −8: trong C# x % 7 = −1 (dấu theo số bị chia), còn đáp án toán học là 6. Công thức (x % m + m) % m luôn cho kết quả trong [0, m). 20! mod (10^9 + 7) = 146326063."}},{label:"Ví dụ: Lũy thừa nhanh",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nlong long luyThua(long long a, long long b, long long m) {\n    long long kq = 1 % m;\n    a %= m;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % m;    // bit thấp nhất của b bật\n        a = a * a % m;                 // a, a^2, a^4, a^8, ...\n        b >>= 1;\n    }\n    return kq;\n}\n\nint main() {\n    cout << luyThua(3, 13, 1000) << \"\\n\";\n    cout << luyThua(2, 1000000000000000000LL, 1000000007) << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","kq"]}],py:{code:"def luy_thua(a, b, m):\n    kq = 1 % m\n    a %= m\n    while b > 0:\n        if b & 1:                      # bit thấp nhất của b bật\n            kq = kq * a % m\n        a = a * a % m                  # a, a^2, a^4, a^8, ...\n        b >>= 1\n    return kq\n\nprint(luy_thua(3, 13, 1000))\nprint(luy_thua(2, 10 ** 18, 1000000007))\nprint(pow(2, 10 ** 18, 1000000007))    # hàm có sẵn của Python làm đúng việc này",note:"3^13 = 1594323, ba chữ số cuối 323. Python có sẵn pow(a, b, m) dùng cùng thuật toán."},cs:{code:"using System;\n\nclass Program\n{\n    static long LuyThua(long a, long b, long m)\n    {\n        long kq = 1 % m;\n        a %= m;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % m;   // bit thấp nhất của b bật\n            a = a * a % m;                 // a, a^2, a^4, a^8, ...\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(LuyThua(3, 13, 1000));\n        Console.WriteLine(LuyThua(2, 1000000000000000000L, 1000000007));\n    }\n}"}},{label:"Lỗi: tràn số khi nhân trước khi lấy dư",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    const int M = 1000000007;\n    int a = 1000000, b = 1000000;\n    int sai = a * b % M;               // SAI: a * b tính bằng int, tràn trước khi % M\n    long long dung = 1LL * a * b % M;  // ép sang long long trước khi nhân\n    cout << sai << \" \" << dung << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","sai","dung"]}],py:{code:"import math\nM = 1000000007\nsai = int(math.pow(3, 40)) % M        # SAI: math.pow tính bằng số thực, mất chữ số\ndung = pow(3, 40, M)\nprint(sai, dung)",label:"Lỗi: dùng số thực để tính lũy thừa",note:"Python không tràn số nguyên, nhưng math.pow trả về số thực: 3^40 có 20 chữ số, vượt độ chính xác của float (khoảng 15–16 chữ số), nên phần đuôi sai và phần dư sai theo. Luôn dùng pow(a, b, m) hoặc ** với số nguyên."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const int M = 1000000007;\n        int a = 1000000, b = 1000000;\n        int sai = a * b % M;                   // SAI: a * b tính bằng int, tràn trước khi % M\n        long dung = (long)a * b % M;           // ép sang long trước khi nhân\n        Console.WriteLine(sai + \" \" + dung);\n    }\n}",note:"10^6 · 10^6 = 10^12 vượt xa giới hạn int (khoảng 2,1 · 10^9): C# mặc định không kiểm tra tràn, kết quả quấn vòng thành −727379968. Đáp án đúng 999993007. Viết (long)a * b hoặc khai báo long ngay từ đầu."}}];
